struct Reading { label: Str, values: Vec<Int> }

fn first_big(v: Vec<Int>) -> Int {
    let mut found = -1;
    for x in v {
        if x > 5 {
            found = x;
            break;
        }
    }
    found
}

fn second(v: Vec<Int>) -> Option<Int> {
    let x = get(v, 1)?;
    Some(x + 1)
}

fn main() {
    let r = Reading { label: "lab", values: push(push(vec(), 6), 11) };
    let count_above_five = first_big(r.values);
    print(count_above_five);            // field access copies: r stays usable
    let r2 = Reading { label: "lab2", ..r };
    match second(r2.values) {
        Some(n) => print(n),
        None => print_str("too short"),
    }
}

